from pathlib import Path
import json,re,html,collections
root=Path(__file__).parent;d=root/'dist';e=html.escape
corpus=json.loads((root/'recruiter-data'/'evidence.json').read_text())
(d/'recruiter-evidence.json').write_text(json.dumps(corpus,ensure_ascii=False,indent=2)+'\n')
base=(d/'index.html').read_text()
header=re.search(r'<header.*?</header>',base,re.S).group()
header=header.replace('href="#','href="./#')
header=header.replace('href="recruiters.html"','href="recruiters.html" aria-current="page"')
footer=re.search(r'<footer.*?</footer>',base,re.S).group().replace('href="#main"','href="#main"')
groups=collections.OrderedDict()
for s in corpus['skills']: groups.setdefault(s['category'],[]).append(s)
labels={'profile-listed':'Listed in GitHub profile','self-reported':'Confirmed by Matthew','education':'Education','cv-listed':'Listed in résumé','cv-role':'Role evidence','project':'Project source'}
cards='';browse=[]
for i,(group,skills) in enumerate(groups.items()):
 gid='category-'+str(i);browse.append(f'<a href="#{gid}">{e(group)}</a>')
 cards+=f'<section class="recruiter-category" id="{gid}"><h3>{e(group)}</h3><div class="recruiter-skills">'
 for s in skills:
  cards+=f'<details class="recruiter-skill" id="skill-{e(s["id"])}"><summary>{e(s["label"])}</summary>'
  for v in s['evidence']:
   cards+=f'<p class="evidence-label">{labels[v["kind"]]}</p><p>{e(v["quote"])}</p><a href="{e(v["url"])}">{e(v["section"])}</a>'
  
   if v.get('contextUrl'): cards+=f'<p><a href="{e(v["contextUrl"])}">{e(v["contextLabel"])}</a></p>'
   if v.get('limitation'): cards+=f'<p class="recruiter-footnote">{e(v["limitation"])}</p>'
  cards+='</details>'
 cards+='</div></section>'
career=re.search(r'<div class="career-head">.*?(?=</section>\s*<section class="section (?:wrap technical-experience|archive)")',base,re.S).group()
for company in ['Paperly','CitoPlus','Lexer','LynkState','SubSpace','Telstra']:
 career=re.sub(r'<li>(<time>[^<]*</time><h5>'+company+r'</h5>)',lambda m:'<li id="career-'+company.lower()+'">'+m.group(1),career)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recruiters · Matthew Aldous · Skills and experience</title><meta name="description" content="Explore Matthew Aldous’s engineering skills, career history and project evidence. Match job requirements to cited public résumé and GitHub sources in your browser."><link rel="canonical" href="https://aldous.info/recruiters.html"><meta name="theme-color" content="#16283e"><script src="theme-init.js"></script><link rel="icon" href="portfolio-assets/monogram.svg" type="image/svg+xml"><link rel="preload" href="fonts/OffMenuRoboto-Regular.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="portfolio.css?v=49"><link rel="stylesheet" href="recruiters.css"></head><body class="recruiter-page"><div class="page-backdrop" aria-hidden="true"></div><a class="skip" href="#main">Skip to content</a>'''+header+'''<main id="main"><section class="wrap recruiter-hero"><h1>Recruiters</h1><p class="recruiter-intro">Explore my cloud, software and engineering experience. Paste a job description or search a technology to find the relevant statements in my résumé and project sources.</p><div class="recruiter-links"><a class="text-link" href="Matthew-Aldous-Resume-2026.pdf">Read my résumé</a><a class="text-link" href="https://github.com/maldous">Explore GitHub</a><a class="text-link" href="#technical-experience">Technical background</a><a class="text-link" href="#skills">Browse evidence</a><a class="text-link" href="#experience">Career history</a></div></section><section class="wrap" aria-label="Find evidence"><div class="recruiter-workspace"><div class="recruiter-panel"><form id="recruiter-search"><label for="requirements">Job description, requirements or a skill</label><p class="recruiter-help" id="input-help">Paste up to 30,000 characters. One requirement per line makes comparison easier.</p><textarea id="requirements" maxlength="30000" aria-describedby="input-help input-privacy" autocomplete="off" spellcheck="false" placeholder="For example: Kubernetes, TypeScript, observability and engineering leadership" disabled></textarea><p id="input-privacy" class="recruiter-help">Your text stays in this browser tab. This tool does not send or save what you paste.</p><div class="recruiter-actions"><button class="button" type="submit" id="recruiter-submit" disabled>Find evidence</button><button class="button recruiter-secondary" type="button" id="recruiter-clear">Clear</button></div></form><div class="recruiter-examples" aria-label="Add an example requirement"><button type="button" data-example="Kubernetes, AWS and release automation">Cloud platforms +</button><button type="button" data-example="TypeScript, Laravel and Vue.js">Full-stack engineering +</button><button type="button" data-example="OpenTelemetry, Sentry and observability">Observability +</button></div><p class="recruiter-status" id="recruiter-status" role="status" aria-live="polite">Loading search. You can browse the evidence below.</p><noscript><p>JavaScript is off. All skills, sources and career history remain available below.</p></noscript></div><aside class="recruiter-panel"><h2>What you’ll find</h2><ul><li>Direct links to résumé statements and project sources.</li><li>Role examples separated from skills listed in the résumé.</li><li>The full requirement beside each match, including anything the lookup does not recognize.</li></ul><p class="recruiter-footnote">This is a term-based evidence lookup, not a suitability score. Years of experience, seniority and other qualifiers need a separate review.</p><p class="recruiter-footnote"><a href="mailto:matthew.aldous@gmail.com">Ask me about a requirement</a></p></aside></div><p class="recruiter-footnote"><a href="#results-heading" id="jump-results" hidden>Jump to results</a></p><div id="recruiter-results" aria-label="Requirement evidence"></div></section><section class="wrap recruiter-directory" id="skills"><h2>Skills, technology and evidence</h2><p>These statements come from my public résumé, GitHub profile and project sources. Open a skill to read the supporting text. A listed skill does not establish its duration, recency or proficiency, and project documentation is not independent verification.</p><nav class="recruiter-browse" aria-label="Skill categories">'''+''.join(browse)+'''</nav>'''+cards+'''<div class="recruiter-bottom" id="languages"><h3>Programming and spoken languages</h3><p><strong>Programming and scripting:</strong> TypeScript, JavaScript, Python, PHP, C, C++, Perl, Go, Bash, Shell scripting, PowerShell, SQL, Java, BASIC, Pascal, Assembly (ASM), Pike, Prolog, PL/SQL, VBScript, Visual Basic, Swift, Kotlin.</p><p><strong>Markup and transformations:</strong> HTML, CSS, XML, XSL, XSLT, XSL-FO, WML, XUL.</p><p>These technologies are listed in my <a href="https://github.com/maldous/maldous/blob/b588b6bfabd0df548ba6a463ba4814f8df80dc74/README.md">GitHub profile</a>. Supporting résumé and project evidence appears in the searchable directory above.</p><p><strong>Spoken languages:</strong> I speak English and Dutch.</p></div></section><section class="section wrap" id="experience">'''+career+'''<div class="recruiter-bottom"><h3>Keep the context</h3><p>Career dates describe roles, not years using each technology. Project evidence retains research, prototype and archived status where applicable. This page provides readable text and source links for people and indexing tools; compatibility with a particular ATS is not guaranteed.</p><div class="recruiter-links"><a class="text-link" href="Matthew-Aldous-Resume-2026.pdf">Download résumé</a><a class="text-link" href="./#work">Browse projects</a><a class="text-link" href="mailto:matthew.aldous@gmail.com">Contact Matthew</a></div></div></section></main>'''+footer+'''<script type="module" src="recruiters.mjs?v=45"></script></body></html>'''
page=page.replace('<section class="wrap recruiter-directory"', (root/'recruiter-data'/'technical-experience.html').read_text()+'<section class="wrap recruiter-directory"',1)
(d/'recruiters.html').write_text(page)
